import{_ as e,o as i,c as t,ae as s}from"./chunks/framework.DBosx3SP.js";const u=JSON.parse('{"title":"Analytical Anti-Aliasing","description":"","frontmatter":{},"headers":[],"relativePath":"rendering/analytical-anti-aliasing.md","filePath":"rendering/analytical-anti-aliasing.md","lastUpdated":1792899449000}'),n={name:"rendering/analytical-anti-aliasing.md"};function r(l,a,d,o,c,h){return i(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="analytical-anti-aliasing" tabindex="-1">Analytical Anti-Aliasing <a class="header-anchor" href="#analytical-anti-aliasing" aria-label="Permalink to &quot;Analytical Anti-Aliasing&quot;">​</a></h1><p>Shaders evaluate signed distance fields (SDFs) and use the results to blend neighboring pixels.</p><h2 id="sdfs" tabindex="-1">SDFs <a class="header-anchor" href="#sdfs" aria-label="Permalink to &quot;SDFs&quot;">​</a></h2><h3 id="markers-lines-and-quadratic-bezier-curves" tabindex="-1">Markers, Lines, and Quadratic Bezier Curves <a class="header-anchor" href="#markers-lines-and-quadratic-bezier-curves" aria-label="Permalink to &quot;Markers, Lines, and Quadratic Bezier Curves&quot;">​</a></h3><p>Use the SDFs described at <a href="https://iquilezles.org/articles/distfunctions2d/" target="_blank" rel="noreferrer">https://iquilezles.org/articles/distfunctions2d/</a>.<br> Alpha transitions from 1.0 at <code>dist = -0.5</code>, through 0.5 at <code>dist = 0.0</code>, to 0.0 at <code>dist = +0.5</code>.</p><h2 id="subpixel-sdf" tabindex="-1">Subpixel SDF <a class="header-anchor" href="#subpixel-sdf" aria-label="Permalink to &quot;Subpixel SDF&quot;">​</a></h2><p>For objects such as circles and lines that are smaller than 1 px, we draw them at 1 px and adjust their alpha.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1px + alpha     1px</span></span>
<span class="line"><span>░▓░ ← fades out ▓█▓ ← preserved</span></span>
<span class="line"><span>░▓░             ▓█▓</span></span></code></pre></div><h2 id="numerical-stability" tabindex="-1">Numerical Stability <a class="header-anchor" href="#numerical-stability" aria-label="Permalink to &quot;Numerical Stability&quot;">​</a></h2><h3 id="fwidth" tabindex="-1">fwidth <a class="header-anchor" href="#fwidth" aria-label="Permalink to &quot;fwidth&quot;">​</a></h3><p><code>fwidth</code> is unstable at discontinuities. For now, <code>pixel_size</code> is fixed at <code>1.0</code>.</p><h3 id="cubic-bezier" tabindex="-1">Cubic Bezier <a class="header-anchor" href="#cubic-bezier" aria-label="Permalink to &quot;Cubic Bezier&quot;">​</a></h3><p>There is no closed-form SDF for the distance between a given point and a cubic Bezier curve.<br> The distance must be approximated with an iterative Newton method. This is slow and still inaccurate, so we instead approximate each cubic Bezier curve with two quadratic Bezier curves.</p><h3 id="joints" tabindex="-1">Joints <a class="header-anchor" href="#joints" aria-label="Permalink to &quot;Joints&quot;">​</a></h3><h3 id="overlapping-and-seams" tabindex="-1">Overlapping and Seams <a class="header-anchor" href="#overlapping-and-seams" aria-label="Permalink to &quot;Overlapping and Seams&quot;">​</a></h3><p>Analytical anti-aliasing (AAA) causes problems when an object is drawn with multiple adjacent geometries.</p><p>Two rectangles spanning <code>x</code> in <code>[0, 1]</code> and <code>[1, 2]</code> produce semitransparent pixels around <code>x = 1</code>.</p><p>TODO: Define a strategy for eliminating these seams.</p>`,18)])])}const b=e(n,[["render",r]]);export{u as __pageData,b as default};
